const V3_KIND={sync:['同步窗口','window'],open:['批量打开','window'],close:['批量关闭','window'],bind:['批量设置代理','window'],import:['批量导入','proxy'],check:['批量检测','proxy'],singleCheck:['代理检测','proxy']};
function v3Fixture(kind='open',phase='processing'){const isProxy=['import','check','singleCheck'].includes(kind),idx=kind==='singleCheck'?[v3Proxy]:v3Selection.length?v3Selection:kind==='open'?[1,3]:kind==='close'?[0,2,6]:[0,1,2],arr=kind==='import'?importAddresses:kind==='sync'?V3_WINDOWS.map(r=>r.name):kind==='check'?V3_PROXIES.slice(0,6).map(r=>r.name):idx.map(i=>isProxy?V3_PROXIES[i].name:V3_WINDOWS[i].name);const f={kind,phase,module:V3_KIND[kind][1],items:arr.map((label,i)=>({id:kind==='import'?i+1:isProxy?V3_PROXIES[kind==='singleCheck'?v3Proxy:i].id:V3_WINDOWS[kind==='sync'?i:idx[i]].id,label,status:'pending',reason:''})),indices:idx};if(kind==='import'){f.items[4].status='skip';f.items[4].reason='已存在相同资源';f.items[5].status='skip';f.items[5].reason='无效行未选择导入'}if(phase==='processing'){f.items.filter(x=>x.status==='pending').slice(0,Math.max(0,Math.floor(f.items.length/3))).forEach(x=>{x.status='success';x.reason='已确认完成'});const next=f.items.find(x=>x.status==='pending');if(next)next.status='processing'}else if(phase==='partial'){f.items.forEach(x=>{if(x.status==='pending'){x.status='success';x.reason='已确认完成'}});const last=f.items.filter(x=>x.status==='success').at(-1);last.status='failed';last.reason=kind==='import'?'保存失败，请重试':'操作未完成，请重试'}else if(phase==='interrupted'){f.items[0].status='success';f.items[0].reason='已完成，结果保留';if(f.items[1]){f.items[1].status='uncertain';f.items[1].reason='连接中断，需核实是否生效'}}else if(phase==='uncertain'){f.items.forEach((x,i)=>{x.status=i===0?'success':'uncertain';x.reason=i===0?'已确认完成':'结果尚未确认，先核实'})}else if(phase==='failed'){f.items.forEach(x=>{x.status='failed';x.reason='连接失败，本次未完成'})}else if(phase==='success'){f.items.forEach(x=>{if(!['skip'].includes(x.status)){x.status='success';x.reason='已确认完成'}})}return f}
function v3Counts(f){return ['success','failed','skip','processing','pending','uncertain'].map(k=>f.items.filter(x=>x.status===k).length)}
function v3FlowPanel(f){const processing=f.phase==='processing',counts=v3Counts(f),attention=f.phase==='interrupted'||counts[5]>0,fatal=counts[1]===f.items.length,title=V3_KIND[f.kind][0]+(f.retry?' · 重试结果':''),labels={success:['成功','green'],failed:['失败','red'],skip:['跳过',''],processing:['处理中','blue'],pending:['未处理',''],uncertain:['待确认','orange']};const heading=processing?title+'中':f.phase==='interrupted'?'操作已中断':f.phase==='uncertain'?'部分结果待确认':counts[1]===f.items.length?'本次处理失败':counts[1]?'处理结束，部分未完成':'处理完成';const body=`<div class="result-head"><div class="result-icon ${processing||attention?'orange':fatal?'red':counts[1]?'orange':'green'}">${processing?'<span class="spin"></span>':icon(counts[1]||attention?'InfoCircle':'CheckCircle')}</div><h2>${heading}</h2><p>${processing?'请保持此窗口打开，完成后自动展示结果。':f.phase==='interrupted'?'已完成项目保留；未处理项可重新选择，待确认项先核实。':f.phase==='uncertain'?'先核实实际配置，避免重复操作。':'本次结果仅在当前窗口查看。'}</p></div><div class="flow-counts">${[[f.items.length,'总数'],...counts.map((n,i)=>[n,['成功','失败','跳过','处理中','未处理','待确认'][i]])].map(([n,t])=>`<div><strong>${n}</strong><span>${t}</span></div>`).join('')}</div>${processing?`<div class="progress"><span style="width:${100*(counts[0]+counts[1]+counts[2])/f.items.length}%"></span></div><p class="tiny muted">已处理 ${counts[0]+counts[1]+counts[2]} / ${f.items.length} 项　${f.items.find(x=>x.status==='processing')?.label||''}</p>`:''}<table class="dense flow-items"><thead><tr><th>${f.kind==='import'?'原行号':'ID'}</th><th>${f.module==='proxy'?'代理 / 输入内容':'窗口'}</th><th>结果</th><th>原因 / 后续</th></tr></thead><tbody>${f.items.map(x=>`<tr><td>${x.id}</td><td>${x.label}</td><td>${badge(...labels[x.status])}</td><td class="tiny subtle">${x.reason||(x.status==='processing'?'正在处理':x.status==='pending'?'尚未开始':'—')}</td></tr>`).join('')}</tbody></table>`;let footer=processing?'<span class="tiny muted">处理中不可关闭；强制离开不会撤销已生效项目。</span>':(counts[1]?btn('重试失败项','flow-retry'):'')+(counts[5]?btn('核实待确认项','!v3-verify-flow'):'')+btn('完成','!v3-close','primary');let out=v3Dialog(title,body,footer,'wide');if(processing)out=out.replace(/<button class="close"[\s\S]*?<\/button>/,'');return out}
function v3Begin(kind,retryItems,prepared){clearTimeout(v3Timer);v3Token++;v3Freeze=false;v3Flow=v3Fixture(kind,'processing');if(prepared)v3Flow.items=prepared;else if(retryItems)v3Flow.items=retryItems.map(x=>({...x,status:'pending',reason:''}));else v3Flow.items.forEach(x=>{if(!['skip'].includes(x.status)){x.status='pending';x.reason=''}});v3Flow.retry=!!retryItems;v3Flow.phase='processing';v3Go(kind==='import'?'flow-import-progress':'flow-progress',true,{flow:true});v3Advance(v3Token)}
function v3Advance(token){if(token!==v3Token||!v3Flow||v3Flow.phase!=='processing')return;const item=v3Flow.items.find(x=>x.status==='pending');if(!item){v3Flow.phase='success';v3Go(v3Flow.retry?'flow-retry-result':v3Flow.kind==='sync'?'w-sync-issues':v3Flow.kind==='import'?'p-import-result':v3Flow.kind==='check'?'p-batch-check':v3Flow.kind==='singleCheck'?'p-check-result':'w-batch-result',true,{flow:true});return}item.status='processing';v3Render();v3Timer=setTimeout(()=>{if(token!==v3Token)return;item.status=v3Flow.kind==='import'&&item.id===4?'failed':'success';item.reason=item.status==='failed'?'保存失败，请重试':'已确认完成';if(['open','close'].includes(v3Flow.kind)){const r=V3_WINDOWS.find(r=>r.id===item.id);if(r)r.running=v3Flow.kind==='open'}v3Advance(token)},480)}
function v3Retry(){const f=v3Flow||v3Fixture('bind','partial'),failed=f.items.filter(x=>x.status==='failed');return v3Dialog('重试失败项',facts([['本次失败',failed.length+' 项'],['重试范围','仅本次失败项'],['不会重复处理','已成功、跳过及结果待确认的项目']])+`<table class="dense" style="margin-top:18px"><thead><tr><th>ID / 原行号</th><th>内容</th><th>失败原因</th></tr></thead><tbody>${failed.map(x=>`<tr><td>${x.id}</td><td>${x.label}</td><td>${x.reason}</td></tr>`).join('')}</tbody></table>`,btn('取消','!v3-return-result')+btn('确认重试','!v3-retry-submit','primary'))}
