document.addEventListener('click',event=>{const t=event.target.closest('[data-go],[data-action],[data-v3],.close');if(!t)return;const inside=t.closest('#stage,#catalog,#book-header');if(!inside)return;event.stopImmediatePropagation();if(t.disabled)return;if(v3Flow?.phase==='processing'&&t.closest('#stage')){showToast('处理中，完成后即可关闭','orange');return}const wr=t.closest('[data-v3-row]'),pr=t.closest('[data-v3-proxy-row]');if(wr)v3Focus=Number(wr.dataset.v3Row);if(pr)v3Proxy=Number(pr.dataset.v3ProxyRow);if(t.dataset.v3==='toggle-window'){const r=V3_WINDOWS[v3Focus];if(!r.enabled){r.enabled=true;v3Render();showToast('窗口已启用')}else v3Go('w-disable');return}if(t.dataset.v3==='toggle-proxy'){v3Go('p-paused');return}if(t.dataset.v3==='stat'){v3StatusFilter=t.dataset.value;v3Filter();return}if(t.dataset.go==='w-self-success'){v3ReleaseProxy();V3_WINDOWS[v3Focus].mode='self'}if(t.dataset.go==='w-replace-confirm'){v3RememberCandidate()}if(t.dataset.go){v3Go(t.dataset.go,true,{catalog:!!t.closest('#catalog')});return}v3Action(t.dataset.action||'v3-close',t)},true);
