function v3RememberCandidate(){const checked=document.querySelector('input[name="proxy-choice"]:checked');if(checked){const row=checked.closest('tr');v3Candidate=[...row.parentNode.children].indexOf(row)}}
const v3OriginalAction=v3Action;
v3Action=function(a,t){if(a==='v3-batch-check'){const chosen=[...document.querySelectorAll('[data-v3-proxy-select]:checked')].map(n=>Number(n.dataset.v3ProxySelect));if(!chosen.length)return;v3Begin('check',null,chosen.map(i=>({id:V3_PROXIES[i].id,label:V3_PROXIES[i].name,status:'pending',reason:''})));return}if(a==='v3-import-submit'){const rows=[...document.querySelectorAll('[data-v3-import-select]')].map((n,i)=>({id:i+1,label:n.closest('tr').cells[2].querySelector('input')?.value||n.closest('tr').cells[2].textContent,status:n.checked?'pending':'skip',reason:n.checked?'':i===4?'已存在相同资源':'未选择导入'}));v3Begin('import',null,rows);return}if(a==='bind-proxy'||a==='replace-proxy'){v3RememberCandidate();const p=V3_PROXIES[v3Candidate],r=V3_WINDOWS[v3Focus];if(p.used>=p.max||['expired','fail','unknown'].includes(p.check)){v3Go('w-bind-empty');return}if(r.proxyName!==p.name||r.mode!=='system'){v3ReleaseProxy();p.used++}Object.assign(r,{mode:'system',proxyName:p.name,address:p.address,issue:'normal'});v3Go(v3Base('window'));showToast('代理已应用');return}if(a==='resync-proxy'){const r=V3_WINDOWS[v3Focus],p=V3_PROXIES.find(p=>p.name===r.proxyName);if(p)r.address=p.address;r.issue='normal';v3Go(v3Base('window'));showToast('托管代理已应用');return}if(a==='unbind-proxy'){v3ReleaseProxy();Object.assign(V3_WINDOWS[v3Focus],{mode:'self',address:'—',proxyName:'无代理 · 直连',issue:'normal'});v3Go(v3Base('window'));showToast('已改为直连');return}if(a==='v3-toggle-proxy'){V3_PROXIES[v3Proxy].enabled=!V3_PROXIES[v3Proxy].enabled;v3Go(v3Base('proxy'));showToast('资源启停已更新');return}if(a==='save-note'){V3_WINDOWS[v3Focus].note=v3Read('运营备注');v3Go(v3Base('window'));showToast('运营备注已保存');return}if(a==='v3-save-window'){const name=v3Read('窗口名称');if(!name){v3OriginalAction(a,t);return}Object.assign(V3_WINDOWS[v3Focus],{name,group:v3Read('比特分组'),tags:v3Read('比特标签').split(/[，,]/),bitNote:v3Read('比特备注')});v3Go(v3Base('window'));showToast('窗口信息已保存');return}if(a==='v3-create-window'&&v3Read('窗口名称')){const record={...V3_WINDOWS[1],id:Math.max(...V3_WINDOWS.map(r=>r.id))+1,name:v3Read('窗口名称'),group:v3Read('比特分组'),tags:v3Read('比特标签').split(/[，,]/),mode:'self',address:'—',proxyName:'无代理 · 直连',issue:'normal',running:false,enabled:true,note:'',team:'星河运营组'};v3CreatedMode=document.querySelector('[name="v3-create-mode"]:checked')?.value||'self';V3_WINDOWS.push(record);v3Focus=V3_WINDOWS.length-1;v3NewWindow=record;v3Go('w-create-success');return}v3OriginalAction(a,t)};
v3Created=function(){const r=v3NewWindow||{name:'B站新号 · 上海05',id:346};return v3Dialog('窗口已创建',resultHead('窗口已创建','')+facts([['窗口名称',r.name],['ID',r.id],['代理方式',v3CreatedMode==='system'?'待选择托管代理':'比特自管']]),btn('完成','!v3-close')+btn(v3CreatedMode==='system'?'选择代理':'配置代理',v3CreatedMode==='system'?'w-bind':'w-mode','primary'))};

// Final interaction consistency for the reviewable prototype.
var v3StatusFilter='',v3Eligible=[];
function v3WindowVisible(r,i){if(v3Role()!=='admin'&&r.team!=='星河运营组')return false;if(v3Team!=='all'&&r.team!==v3Team)return false;if(v3Role()==='admin'&&v3Member==='lin'&&v3Owner(i)!=='林予安')return false;if(v3Role()==='admin'&&v3Member==='chen'&&v3Owner(i)!=='陈以宁')return false;return true}
function v3TableMeta(){const table=document.querySelector('#stage table.resource-table');if(!table)return;table.querySelector('.v3-inline-empty')?.remove();const rows=[...table.querySelectorAll('tbody tr[data-search]')],visible=rows.filter(n=>!n.hidden);if(!visible.length)table.querySelector('tbody').insertAdjacentHTML('beforeend',`<tr class="v3-inline-empty"><td colspan="${table.querySelectorAll('thead th').length}"><div class="read-only muted" style="text-align:center;padding:34px">暂无符合条件的数据</div></td></tr>`);const count=document.querySelector('#stage .pagination>span');if(count)count.textContent='共 '+visible.length+' 条';document.querySelectorAll('[data-v3-proxy-select]').forEach(n=>{if(n.closest('tr').hidden)n.checked=false});const bar=document.querySelector('.v3-proxy-selection');if(bar){const selected=document.querySelectorAll('[data-v3-proxy-select]:checked').length;bar.hidden=!selected;bar.querySelector('strong').textContent=selected}const valid=new Set(visible.filter(n=>n.hasAttribute('data-v3-row')).map(n=>Number(n.dataset.v3Row)));v3Selection=v3Selection.filter(i=>valid.has(i))}
v3Filter=function(){v3Eligible=[];const filters=[...document.querySelectorAll('#stage .filters select')].filter(n=>!n.matches('[data-v3-member],[data-v3-team]')),keyword=(document.querySelector('[data-v3-search]')?.value||'').toLowerCase();document.querySelectorAll('#stage tr[data-v3-row],#stage tr[data-v3-proxy-row]').forEach(n=>{const proxy=n.hasAttribute('data-v3-proxy-row'),i=Number(proxy?n.dataset.v3ProxyRow:n.dataset.v3Row),r=proxy?V3_PROXIES[i]:V3_WINDOWS[i];let ok=proxy?(v3Role()==='admin'||r.team==='星河运营组')&&(v3Team==='all'||r.team===v3Team):v3WindowVisible(r,i);ok=ok&&n.dataset.search.toLowerCase().includes(keyword);for(const f of filters){const val=f.value;if(val==='全部')continue;const label=f.closest('.field')?.querySelector('label')?.textContent;if(label==='代理方式')ok=ok&&(val==='系统托管'?r.mode==='system':r.mode==='self');else if(label==='业务状态'||label==='资源状态'&&val!=='已到期')ok=ok&&(r.enabled===(val==='启用'));else if(label==='运行状态')ok=ok&&(r.running===(val==='已打开'));else if(label==='资源状态'&&val==='已到期')ok=ok&&r.check==='expired';else if(label==='检测结果')ok=ok&&(val==='正常'?r.check==='ok':val==='连接失败'?r.check==='fail':!['ok','fail'].includes(r.check))}if(!proxy&&ok)v3Eligible.push(i);if(!proxy&&v3StatusFilter)ok=ok&&((r.issue==='normal')===(v3StatusFilter==='normal'));n.hidden=!ok});v3TableMeta();const ns=document.querySelector('.v3-stats [data-value="normal"] strong'),ps=document.querySelector('.v3-stats [data-value="pending"] strong');if(ns&&ps){ns.textContent=v3Eligible.filter(i=>V3_WINDOWS[i].issue==='normal').length;ps.textContent=v3Eligible.filter(i=>V3_WINDOWS[i].issue!=='normal').length}};
const v3RenderFinal=v3Render;
v3Render=function(){v3RenderFinal();const adminTeam=document.querySelector('[data-v3-team]');if(adminTeam)adminTeam.value=v3Team;v3Filter();const normal=document.querySelector('.v3-stats [data-value="normal"] strong'),pending=document.querySelector('.v3-stats [data-value="pending"] strong');if(normal&&pending){const rows=v3Eligible.map(i=>V3_WINDOWS[i]);normal.textContent=rows.filter(r=>r.issue==='normal').length;pending.textContent=rows.filter(r=>r.issue!=='normal').length}};
const v3SaveFinal=v3Action;
v3Action=function(a,t){if(a==='v3-save-proxy'){const name=v3Read('代理名称'),host=v3Read('主机地址'),port=Number(v3Read('端口')),edit=['edit','bound'].includes(v3Current.state),manage=v3Manager(),dynamic=v3Current.state==='api'||edit&&V3_PROXIES[v3Proxy].source==='api';if(!name||(!dynamic&&(!edit||manage)&&(!host||!Number.isInteger(port)||port<1||port>65535))){showToast(!name?'请输入代理名称':'请填写有效主机地址和 1–65535 的端口','orange');return}let r=edit?V3_PROXIES[v3Proxy]:{id:Math.max(...V3_PROXIES.map(r=>r.id))+1,used:0,enabled:true,source:dynamic?'api':'static',check:'unknown',protocol:v3Read('协议'),address:dynamic?'—':host+':'+port,username:v3Read('认证用户名'),password:v3Read('认证密码')};Object.assign(r,{name,region:v3Read('地区'),supplier:v3Read('供应商'),note:v3Read('备注'),tags:v3Read('业务标签').split(/[，,]/),team:v3Read('运营团队')||r.team});if(!edit||manage){r.expiry=v3Read('到期时间');r.max=Number(v3Read('最大窗口数'))||1;if(!dynamic){r.address=host+':'+port;r.protocol=v3Read('协议')}r.username=v3Read('认证用户名');if(v3Read('认证密码'))r.password=v3Read('认证密码')}if(!edit)V3_PROXIES.push(r);v3Go(v3Base('proxy'));showToast('代理资料已保存');return}if(a==='delete-proxy'){if(V3_PROXIES[v3Proxy].used){v3Go('p-delete-blocked');return}V3_PROXIES.splice(v3Proxy,1);v3Go(v3Base('proxy'));showToast('代理已删除');return}v3SaveFinal(a,t)};
v3Render();
const v3ParseFinal=v3Action;
v3Action=function(a,t){if(a==='v3-parse-address'){const value=v3Read('粘贴代理地址');let host='',port='',protocol='socks5',username='',password='';try{if(value.includes('://')){const u=new URL(value);host=u.hostname;port=u.port;protocol=u.protocol.slice(0,-1);username=decodeURIComponent(u.username);password=decodeURIComponent(u.password)}else{[host,port,username='',password='']=value.split(':')}if(!host||!Number(port)||Number(port)>65535)throw new Error();for(const [label,value] of Object.entries({'主机地址':host,'端口':port,'协议':protocol,'认证用户名':username,'认证密码':password})){const f=[...document.querySelectorAll('#stage .field')].find(n=>n.querySelector('label')?.textContent.replace('*','').trim()===label)?.querySelector('input,select');if(f)f.value=value}showToast('地址已解析，请核对后保存')}catch{showToast('地址无法解析，请检查格式和端口','orange')}return}v3ParseFinal(a,t)};
document.addEventListener('input',event=>{if(v3Current.id==='p-quota-error'&&event.target.matches('.dialog input')){const n=Number(event.target.value),valid=Number.isInteger(n)&&n>=Math.max(1,V3_PROXIES[v3Proxy].used);document.querySelector('[data-action="v3-save-quota"]').disabled=!valid;event.target.classList.toggle('error',!valid);const error=event.target.closest('.field').querySelector('.error-text');if(error)error.hidden=valid}},true);
function v3StateBoard(){return `<div class="standalone-board"><h1>状态、字段与信息规范</h1><p class="description">每一种状态对应一个明确问题，配置、实际结果与处理进度分别展示。</p><div class="state-grid"><section class="panel state-card"><h3>代理方式与来源</h3>${facts([['代理方式',badge('系统托管','blue')+' '+badge('比特自管')],['资源来源',badge('静态地址')+' '+badge('动态代理','blue')],['窗口信息','比特分组、比特标签、比特备注'],['运营资料','独立运营备注；窗口不另设业务标签']])}<p class="state-note">社媒账号业务标签、代理资源标签继续保留，各自维护。</p></section><section class="panel state-card"><h3>窗口状态</h3>${facts([['窗口同步',badge('比特中可见','green')+' '+badge('最近同步未找到','orange')],['运行状态',badge('已打开','green')+' '+badge('已关闭')+' '+badge('未知','orange')],['业务启停',badge('启用','green')+' '+badge('停用')],['代理异常',badge('配置不一致','orange')+' '+badge('结果待确认','orange')],['顶部统计','正常 / 待处理；缺失窗口转入清理入口']])}<p class="state-note">仅本人桌面端显示运行状态。先关闭再停用；停用不会自动关闭。</p></section><section class="panel state-card"><h3>代理资源状态</h3>${facts([['资源启停',badge('启用','green')+' '+badge('停用')],['有效期',badge('有效','green')+' '+badge('已到期','red')],['系统检测',badge('未检测')+' '+badge('检测中','blue')+' '+badge('正常','green')+' '+badge('连接失败','red')],['名额',badge('可分配','green')+' '+badge('配额已满','orange')]])}<p class="state-note">启停、到期与检测分开判断；系统检测正常不等于窗口已经应用。</p></section><section class="panel state-card"><h3>现场处理与反馈</h3>${facts([['项目状态',badge('成功','green')+' '+badge('失败','red')+' '+badge('跳过')],['处理中',badge('处理中','blue')+' '+badge('未处理')+' '+badge('待确认','orange')],['等待与恢复','处理中不可普通关闭，结束自动显示结果'],['失败与待确认','失败可按范围重试；待确认先核实']])}<p class="state-note">强制离开不撤销已生效项。空数据使用标准表格内提示，加载失败和无权限分别反馈。</p></section></div></div>`}
V3_LEGACY.status=v3StateBoard;
v3Render();
// Keep applied filters while selecting or opening/closing one row.
const v3RenderKeepFilters=v3Render;
v3Render=function(){const stage=document.getElementById('stage'),signature=[v3Current.id,v3Role(),v3Client,v3Member,v3Team].join('|'),keep=stage.dataset.v3Context===signature,fields=keep?[...stage.querySelectorAll('.filters .field')].map(n=>({label:n.querySelector('label')?.textContent,value:n.querySelector('input,select')?.value})):[];v3RenderKeepFilters();stage.dataset.v3Context=signature;if(keep){for(const saved of fields){if(['运营团队','授权运营'].includes(saved.label))continue;const n=[...stage.querySelectorAll('.filters .field')].find(n=>n.querySelector('label')?.textContent===saved.label)?.querySelector('input,select');if(n)n.value=saved.value}v3Filter()}};
const v3ResetFinal=v3Action;
v3Action=function(a,t){if(a==='v3-reset')document.getElementById('stage').dataset.v3Context='';v3ResetFinal(a,t)};
v3Render();
